#include <stdio.h>

int main(void) {
    float x;
    scanf("%f", &x);
    printf("%d\n", (int) x);
    printf("%f\n", x - ((int) x));
    return 0;
}

#include <stdio.h>

int main(void) {
    int ano, mes, dia;
    scanf("%d-%d-%d", &ano, &mes, &dia);
    printf("%02d/%02d/%04d\n", dia, mes, ano);
    return 0;
}

#include <stdio.h>

int main(void) {
    double deposito;
    scanf("%lf", &deposito);
    printf("%.2f\n", deposito * 1.005);
    return 0;
}

#include <stdio.h>

int main(void) {
    int num;
    scanf("%d", &num);
    printf("%o\n", num);
    printf("%x\n", num);
    return 0;
}

#include <stdio.h>

int main(void) {
    int num1, num2;
    scanf("%d %d", &num1, &num2);
    printf("%d\n", num1 + num2);
    printf("%d\n", num1 - num2);
    printf("%d\n", num1 * num2);
    printf("%d\n", num1 / num2);
    printf("%.2f\n", (float)(num1 + num2) / 2.0);
    return 0;
}

#include <stdio.h>

int main(void) {
    double sm, qtdade, preco, vp, vd;
    scanf("%lf %lf", &sm, &qtdade);
    preco = sm / 700.0;
    vp = preco * qtdade;
    vd = vp * 0.9;
    printf("%.2f\n", preco);
    printf("%.2f\n", vp);
    printf("%.2f\n", vd);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double base, altura, perimetro, area, diagonal;
    scanf("%lf %lf", &base, &altura);
    perimetro = 2.0 * (base + altura);
    area = base * altura;
    diagonal = sqrt(base * base + altura * altura);
    printf("%.2f\n", perimetro);
    printf("%.2f\n", area);
    printf("%.2f\n", diagonal);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double a, b, c, diagonal;
    scanf("%lf %lf %lf", &a, &b, &c);
    diagonal = sqrt(a * a + b * b + c * c);
    printf("%.2f\n", diagonal);
    return 0;
}
